package io.github.jesterportfolio.hearth.survival;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
final class WorldTravelTest {
 final UUID player=UUID.randomUUID();final Object token=new Object(),target=new Object();final AtomicLong clock=new AtomicLong();final ArrayDeque<Runnable> queue=new ArrayDeque<>();final WorldTravel core=new WorldTravel(queue::add,clock::get);
 static final class Port implements WorldTravel.Port{boolean current=true,origin=true,atTarget=false,frozen;int moves;final CompletableFuture<Object> prepared=new CompletableFuture<>();final CompletableFuture<Boolean> moved=new CompletableFuture<>();final List<String> notices=new ArrayList<>();public boolean current(){return current;}public boolean atOrigin(){return origin;}public void freeze(boolean b){frozen=b;}public CompletionStage<Object> prepare(SurvivalWorld role){return prepared;}public CompletionStage<Boolean> move(Object target){moves++;return moved;}public boolean atTarget(Object target){return atTarget;}public void notice(String code){notices.add(code);}}
 void pump(){while(!queue.isEmpty())queue.remove().run();}Port begin(){var p=new Port();core.begin(player,token,SurvivalWorld.WILDERNESS,p);return p;}void prepared(Port p){p.prepared.complete(target);pump();}
 @Test void only_prepared_fixed_target_can_move_and_success_unfreezes(){var p=begin();assertTrue(p.frozen);assertEquals(0,p.moves);prepared(p);assertTrue(core.moving(player,token,target));assertFalse(core.moving(player,new Object(),target));assertFalse(core.moving(player,token,new Object()));p.origin=false;p.atTarget=true;p.moved.complete(true);pump();assertFalse(p.frozen);assertFalse(core.busy(player));}
 @Test void preparation_failure_preserves_origin_and_allows_retry(){var p=begin();p.prepared.completeExceptionally(new IllegalStateException());pump();assertEquals(0,p.moves);assertFalse(p.frozen);assertFalse(core.busy(player));}
 @Test void null_preparation_is_a_known_failure(){var p=begin();p.prepared.complete(null);pump();assertFalse(p.frozen);assertEquals(0,p.moves);}
 @Test void unknown_move_or_wrong_result_holds_without_recovery_or_retry(){for(boolean unknown:List.of(true,false)){var local=new WorldTravel(Runnable::run,clock::get);var p=new Port();local.begin(player,token,SurvivalWorld.NETHER,p);p.prepared.complete(target);p.origin=false;if(unknown)p.moved.completeExceptionally(new IllegalStateException());else p.moved.complete(true);assertEquals(WorldTravel.Phase.HOLD,local.phase(player).orElseThrow());assertTrue(p.frozen);assertThrows(IllegalStateException.class,()->local.begin(player,token,SurvivalWorld.NETHER,p));}}
 @Test void definite_false_while_still_at_origin_can_resume(){var p=begin();prepared(p);p.moved.complete(false);pump();assertFalse(p.frozen);assertFalse(core.busy(player));}
 @Test void timeout_revokes_native_teleport_permit_and_late_result_stays_hold(){var p=begin();prepared(p);clock.set(10000);core.tick();assertFalse(core.moving(player,token,target));p.origin=false;p.atTarget=true;p.moved.complete(true);pump();assertTrue(p.frozen);assertEquals(WorldTravel.Phase.HOLD,core.phase(player).orElseThrow());}
 @Test void quit_or_replaced_connection_cannot_apply_late_preparation(){var p=begin();core.quit(player,new Object());assertTrue(core.busy(player));core.quit(player,token);prepared(p);assertEquals(0,p.moves);var next=new Port();core.begin(player,new Object(),SurvivalWorld.NETHER,next);assertTrue(core.busy(player));}
 @Test void previous_native_result_cannot_complete_or_unfreeze_a_new_life(){var p=begin();prepared(p);core.quit(player,token);var next=new Port();var nextToken=new Object();core.begin(player,nextToken,SurvivalWorld.NETHER,next);p.origin=false;p.atTarget=true;p.moved.complete(true);pump();assertTrue(next.frozen);assertEquals(WorldTravel.Phase.PREPARING,core.phase(player).orElseThrow());assertTrue(p.frozen);}
 @Test void stale_and_changed_origin_block_move(){for(boolean stale:List.of(true,false)){var local=new WorldTravel(Runnable::run,clock::get);var p=new Port();local.begin(player,token,SurvivalWorld.WILDERNESS,p);if(stale)p.current=false;else p.origin=false;p.prepared.complete(target);assertEquals(0,p.moves);assertEquals(WorldTravel.Phase.HOLD,local.phase(player).orElseThrow());}}
 @Test void duplicate_click_and_close_cannot_create_another_move(){var p=begin();assertThrows(IllegalStateException.class,()->core.begin(player,token,SurvivalWorld.NETHER,p));core.close();prepared(p);assertEquals(0,p.moves);assertThrows(IllegalStateException.class,()->begin());}
}
